from typing import TypedDict
from langgraph.graph import StateGraph, START, END

class State(TypedDict):
    request: str
    kind: str
    reply: str

def route(state: State) -> dict:
    kind = "greet" if "hello" in state["request"].lower() else "echo"
    return {"kind": kind}

def greet(state: State) -> dict:
    return {"reply": "Hello!"}

def echo(state: State) -> dict:
    return {"reply": state["request"]}

def pick(state: State) -> str:
    return state["kind"]

def build_graph():
    g = StateGraph(State)
    g.add_node("route", route)
    g.add_node("greet", greet)
    g.add_node("echo", echo)
    g.add_edge(START, "route")
    # conditional edge maps router return values to node names
    g.add_conditional_edges("route", pick, {"greet": "greet", "echo": "echo"})
    g.add_edge("greet", END)
    g.add_edge("echo", END)
    return g.compile()

